// The VPU-mixer model, and the derivations built on it.
//
// Pure: no Node APIs, no DOM. The browser imports this directly and the server
// imports it too, so a live read and a recorded capture go through identical
// code on their way to the screen.
//
// A "VPU" on a LivePremier is a *VPU mixer*: the physical mixing/scaling
// resource the device allocates to a (screen, layer) pair. A layer too wide for
// one mixer is split across several, each carrying one `slice`. That is why the
// mixer table — not the layer count — is the real answer to "will this fit".

export const PROCESSORS = 4;
export const MIXERS_PER_PROCESSOR = 16;
export const MAX_MIXERS = PROCESSORS * MIXERS_PER_PROCESSOR; // 64

/** Every mixer id the model allows, in chassis order. */
export const MIXER_IDS = (() => {
  const ids = [];
  for (let p = 1; p <= PROCESSORS; p++) {
    for (let m = 1; m <= MIXERS_PER_PROCESSOR; m++) ids.push(`PROC_${p}_MIXER_${m}`);
  }
  return ids;
})();

export const SCALERS = ['A', 'B'];

/** Output pipes per mixer — one per output link. */
export const OUT_PIPES = 8;

/** Props read from each mixer. All are readOnly in the device's own model. */
export const MIXER_PROPS = [
  'isEnabled',
  'cutnfillCapa',
  'usedInScreen',
  'usedInLayer',
  'channel',
  'slice',
  'capability',
  'seamlessCapa',
];

export const LAYER_CAPABILITIES = ['OFF', 'DUAL', '4K', '3', '5K', '5', '6', '7', '8K'];

export function parseMixerId(id) {
  const m = /^PROC_(\d+)_MIXER_(\d+)$/.exec(id);
  if (!m) return null;
  return { processor: Number(m[1]), index: Number(m[2]) };
}

/**
 * Derive the summary the UI leads with: how much hardware is fitted, how much
 * is spent, and which (screen, layer) runs it was spent on.
 */
export function summarise(mixers) {
  const entries = Object.entries(mixers || {});
  const fitted = entries.filter(([, r]) => r && r.isAvailable);
  const enabled = fitted.filter(([, r]) => r.isEnabled);

  const processors = new Map();
  for (const [id, rec] of entries) {
    const parsed = parseMixerId(id);
    if (!parsed) continue;
    if (!processors.has(parsed.processor)) {
      processors.set(parsed.processor, { processor: parsed.processor, fitted: 0, enabled: 0 });
    }
    const bucket = processors.get(parsed.processor);
    if (rec && rec.isAvailable) bucket.fitted++;
    if (rec && rec.isEnabled) bucket.enabled++;
  }

  // Group enabled mixers into the (screen, layer) runs a layer actually costs.
  const groups = new Map();
  for (const [id, rec] of enabled) {
    const key = `${rec.usedInScreen} ${rec.usedInLayer}`;
    if (!groups.has(key)) {
      groups.set(key, {
        screen: rec.usedInScreen,
        layer: rec.usedInLayer,
        capability: rec.capability,
        mixers: [],
        slices: [],
        pipes: new Set(),
      });
    }
    const g = groups.get(key);
    g.mixers.push(id);
    g.slices.push(rec.slice);
    const a = rec.mixerAllocation || {};
    for (let k = 1; k <= OUT_PIPES; k++) {
      const v = a[`usedOnOutPipe${k}`];
      if (v !== undefined && v !== null && v !== 'NONE') g.pipes.add(`link ${k}\u2192out ${v}`);
    }
  }

  const allocations = [...groups.values()]
    .map((g) => ({ ...g, slices: [...g.slices].sort((a, b) => a - b), pipes: [...g.pipes] }))
    .sort((a, b) => {
      const sa = String(a.screen);
      const sb = String(b.screen);
      if (sa !== sb) return sa.localeCompare(sb, undefined, { numeric: true });
      if (a.layer === 'NATIVE') return -1;
      if (b.layer === 'NATIVE') return 1;
      return String(a.layer).localeCompare(String(b.layer), undefined, { numeric: true });
    });

  return {
    fitted: fitted.length,
    enabled: enabled.length,
    spare: fitted.length - enabled.length,
    max: MAX_MIXERS,
    screens: new Set(allocations.map((a) => a.screen)).size,
    processors: [...processors.values()].sort((a, b) => a.processor - b.processor),
    allocations,
  };
}

/* ------------------------------------------------------------------------ *
 * The link grid — the way Analog Way's own manual draws a VPU.
 *
 * A VPU is an 8x8 field of links: 8 layer links in on the left, 8 output links
 * out through the top and bottom (User Manual v6.0 §5.5). A layer occupies a
 * square block sized by its capacity — capacity 1 is 1x1 links, capacity 2 is
 * 2x2, capacity 4 is 4x4 — so a VPU holds 64 capacity-1 layers, 16 capacity-2
 * ones, or 4 capacity-4 ones.
 *
 * §5.5.4: a VPU spreads a layer over at most 4 output links. A layer wider than
 * that consumes a second layer link and wraps onto it.
 *
 * ---------------------------------------------------------------------------
 * HOW MUCH OF THIS THE DEVICE ACTUALLY REPORTS — settled on hardware 2026-08-21.
 *
 * COLUMNS ARE REPORTED. `mixerAllocation.usedOnOutPipe1..8` names exactly which
 * output links a mixer drives. Every mixer in a (screen, layer) run shares the
 * same set, and different runs sit on different links — on the captured Aquilon C,
 * S1 on links 1 and 3, S3 on 2 and 4, S2 on 5 and 7. Note the interleaving: runs
 * are NOT allocated contiguous links, so the grid must draw what is reported
 * rather than forcing each mixer into a contiguous square.
 *
 * ROWS ARE NOT NAMED, BUT THEY ARE CONSTRAINED. Nothing in the mapping says which
 * layer link a mixer sits on. What the grid must not do, though, is invent a
 * layout that the hardware cannot have: THE FIELD IS A CROSSPOINT MATRIX. A row is
 * one layer-capacity link carrying ONE layer; a column is one output-capacity
 * link. Both are dual-link — capacity 1 in Analog Way's terms — and a layer need
 * not match the capacity of the outputs it feeds. One layer may span several
 * output links, and one output link may carry several layers (that is what
 * compositing is), but no two layers may share a row.
 *
 * Until 2026-08-21 this function packed rows instead: a run took one row per
 * slice, placed at the first row where its columns were free, so runs on disjoint
 * links shared rows. That drew S1, S2 and S3 all on layer link 1 of the captured
 * VPU 1 — three layers on one link, which the hardware cannot do. Rows are now
 * allocated exclusively, in the device's own mixer order.
 *
 * HOW TALL A RUN IS: its capability, via `capacityToLinks` — DUAL 1, 4K 2, 5K 4 —
 * floored at the number of distinct column sets its mixers form, since a layer
 * spread past 4 output links is carried by a second mixer on further links
 * (§5.5.4) and each of those needs a link of its own. Slices do NOT add rows: the
 * mixers of one slice-run are the same layer on the same links, so they share
 * their rows and are drawn as one block.
 *
 * THE CENTRE LINE BOUNDS A LINK. A layer-capacity link cannot cross the
 * scaling-engine boundary at four output links, so a layer reaching both halves
 * wraps onto another layer link for the far half even when one mixer reports the
 * whole reach. On the optimized capture this is what fills VPU 1 exactly: S1's
 * two layers take three links each, and S2's layer starts at link 7 rather than
 * riding up beside them.
 *
 * NATIVE BACKGROUNDS DO NOT SPEND LAYER CAPACITY. A screen's native background is
 * reported like a layer, holds mixers and drives output links, but it is not one
 * of the eight layer-capacity links. It is laid out in a separate band
 * (`section: 'background'`, rows numbered from LINKS_PER_VPU up, so they cannot
 * be mistaken for the eight) and `rowsUsed` counts layer rows only. Renderers
 * draw that band ABOVE the field: an output link runs down through a VPU, and
 * the native is the bottom of the stack — the first thing on the link, with
 * layer 1 composited over it, then 2, and so on down the field.
 *
 * A SCREEN CAN CONTINUE ONTO ANOTHER VPU. When a VPU's sixteen mixers are spent,
 * a screen's next layer is allocated on the next VPU, on the SAME output links —
 * the base capture has S3's native on VPU 1 and its layer 1 on VPU 2. The output
 * link leaves the bottom of the first VPU and enters the top of the second, so
 * the second continues the stack: its `screens` entry carries `from` (the VPU it
 * continues), the first's carries `to`, and the screen keeps the same columns on
 * both so the link is drawn straight down (`stackVpus` orders the cards). This is
 * NOT §5.5.5's combined VPU, which is a screen too WIDE for one — that one takes
 * further output links on the next VPU, and has never been captured.
 *
 * `$vpuLayer` — which looked like the reported grid, 8 scalers per VPU each
 * declaring 8 output pipes — DOES NOT EXIST on hardware: it answers E12, along
 * with `$pipe`. It is present but permanently empty on the simulator. The two
 * implementations expose different collections; trust the hardware.
 * ------------------------------------------------------------------------ */

export const LINKS_PER_VPU = 8;
export const SCALING_ENGINE_BOUNDARY = 4; // output links, §5.5.4

/**
 * How many links square one layer of a given capability occupies.
 *
 * The device's own LAYER_CAPABILITIES enum is `OFF, DUAL, 4K, 3, 5K, 5, 6, 7,
 * 8K` — and read as a list, its *position* is the capacity: the plain numeric
 * entries sit at exactly their own index (`3` third, `5` fifth, and so on), so
 * the named ones are the capacities that got names. DUAL is 1, 4K is 2, 5K is
 * 4, 8K is 8. The manual only discusses capacities 1, 2 and 4 (§5.5.3).
 *
 * This was originally hard-coded with `8K` at 4 and no entry for `5K` at all,
 * which a chassis reporting `5K` showed up as wrong.
 *
 * Note this only sizes blocks in the DERIVED fallback layout — where the device
 * reports its output links, block position comes from those instead.
 */
export function capacityToLinks(capability) {
  if (capability === 'OFF' || capability === undefined || capability === null) return 0;
  const i = LAYER_CAPABILITIES.indexOf(String(capability));
  if (i > 0) return i;
  const n = Number(capability);
  return Number.isFinite(n) && n > 0 ? n : 2;
}

/**
 * The output links a mixer drives, as the SCREEN numbers them — 1..n over the
 * screen's own outputs.
 *
 * `usedOnOutPipe<k>: '<n>'` is a pair: the key is the VPU pipe the mixer is wired
 * to, the value is which of the screen's output links that pipe carries. The two
 * disagree, and it is the value that the manual draws. A six-output screen reads
 * `usedOnOutPipe1:'1', usedOnOutPipe3:'2', usedOnOutPipe5:'3', usedOnOutPipe7:'4'`
 * on one mixer and `usedOnOutPipe2:'5', usedOnOutPipe4:'6'` on the next: pipes
 * interleaved, but the screen's links 1 to 6, in order and contiguous.
 */
export function reportedOutputs(rec) {
  const a = (rec && rec.mixerAllocation) || {};
  const outs = new Set();
  for (let k = 1; k <= OUT_PIPES; k++) {
    const v = a[`usedOnOutPipe${k}`];
    if (v === undefined || v === null || v === 'NONE') continue;
    const n = Number(v);
    if (Number.isFinite(n) && n > 0) outs.add(n);
  }
  return [...outs].sort((x, y) => x - y);
}

/** The VPU pipes a mixer is wired to, 0-based — the keys, not the columns. */
export function reportedColumns(rec) {
  const a = (rec && rec.mixerAllocation) || {};
  const cols = [];
  for (let k = 1; k <= OUT_PIPES; k++) {
    const v = a[`usedOnOutPipe${k}`];
    if (v !== undefined && v !== null && v !== 'NONE') cols.push(k - 1);
  }
  return cols;
}

/** A screen's native background — reported like a layer, but not one. */
export function isBackground(layer) {
  return String(layer) === 'NATIVE';
}

/**
 * Build the link grid the way the manual draws one (§5.5.2 to §5.5.6).
 *
 * COLUMNS ARE PER SCREEN. Each screen takes a contiguous run of output links,
 * as wide as the number of outputs it uses, and the screens sit side by side in
 * the order the device allocated their mixers — two four-output screens fill a
 * VPU as links 1-4 and 5-8 (§5.5.4). The device's `usedOnOutPipe` KEYS are
 * interleaved and are not that order; its VALUES are (see `reportedOutputs`).
 *
 * ROWS ARE PER LAYER. A row is one layer-capacity link and carries one layer, so
 * every layer gets rows of its own — as many as its capability, DUAL 1, 4K 2,
 * 5K 4 — never shared with another layer.
 *
 * A LAYER'S BAR IS CONTINUOUS, AND BREAKS AT THE CENTRE LINE. A layer spread
 * over more than four output links takes another layer link and wraps onto it
 * (§5.5.4), which is the manual's ↳ hook: a six-output screen's layer is drawn as
 * links 1-4 on one row and 5-6 on the next. Optimized mode lifts that boundary
 * for layers of capacity 2 (§5.5.6), and only for those.
 *
 * A SCREEN CONTINUING FROM AN EARLIER VPU KEEPS ITS COLUMNS. Where a screen's
 * mixers on this VPU drive output links it already drives on an earlier one, the
 * link is running on from that VPU into this one, and the screen is placed on the
 * same columns so the two draw in line when the VPUs are stacked. Other screens
 * fill the columns left, first fit, in allocation order — which is the old
 * side-by-side order whenever nothing continues. If the columns are taken, the
 * screen is placed first fit like any other and the continuation is still
 * recorded; the picture is a jog rather than a straight link, not a lie.
 *
 * @param {object} mixers the mixer table
 * @param {Set<number>} [optimized] processors in Optimized mode, from `optimizedVpus`
 * @returns {{vpu, fitted, blocks, rowsUsed, backgroundRows, screens, columnsUsed,
 *   overflow, spare, placement}[]}
 *   `screens` entries are `{screen, col, width, outputs, from?, to?}`: the screen's
 *   own output links driven on this VPU, and the VPUs it continues from and onto.
 */
export function buildLinkGrid(mixers, optimized) {
  const anyPipes = Object.values(mixers || {}).some(
    (r) => r && r.isEnabled && reportedOutputs(r).length,
  );
  if (!anyPipes) {
    return deriveLinkGrid(mixers).map((g) => ({ ...g, placement: 'derived' }));
  }

  const optimizedVpu = optimized instanceof Set ? optimized : new Set();
  const out = [];

  for (let p = 1; p <= PROCESSORS; p++) {
    const ids = MIXER_IDS.filter((id) => parseMixerId(id).processor === p);
    const fitted = ids.some((id) => mixers?.[id]?.isAvailable);
    const enabled = ids.filter((id) => mixers?.[id]?.isEnabled);

    // (screen, layer) runs, in the device's own mixer order.
    const runs = [];
    const index = new Map();
    for (const id of enabled) {
      const m = mixers[id];
      const key = `${m.usedInScreen} ${m.usedInLayer}`;
      if (!index.has(key)) {
        index.set(key, runs.length);
        runs.push({
          screen: m.usedInScreen,
          layer: m.usedInLayer,
          background: isBackground(m.usedInLayer),
          capability: m.capability,
          cutnfill: m.cutnfillCapa,
          cells: [],
        });
      }
      runs[index.get(key)].cells.push({
        id, slice: m.slice, outputs: reportedOutputs(m), pipes: reportedColumns(m), rec: m,
      });
    }

    // Columns: each screen a contiguous run, as wide as the outputs it uses,
    // screens in the order their mixers were allocated.
    const order = [];
    const width = new Map();
    const links = new Map(); // screen -> the screen's own output links driven here
    for (const run of runs) {
      if (!width.has(run.screen)) {
        width.set(run.screen, 0);
        links.set(run.screen, new Set());
        order.push(run.screen);
      }
      for (const c of run.cells) for (const o of c.outputs) links.get(run.screen).add(o);
      const w = Math.max(0, ...run.cells.flatMap((c) => c.outputs));
      width.set(run.screen, Math.max(width.get(run.screen), w));
    }

    // A screen already on an earlier VPU, on links it drives here too, is
    // continuing from it: the link runs down out of that VPU and into this one,
    // so the screen keeps the columns it had there when they are free.
    const taken = new Set();
    const free = (col, w) => {
      if (col < 0 || col + w > LINKS_PER_VPU) return false;
      for (let c = col; c < col + w; c++) if (taken.has(c)) return false;
      return true;
    };
    const claim = (col, w) => {
      for (let c = col; c < col + w; c++) taken.add(c);
    };
    const base = new Map();
    const from = new Map();
    for (const s of order) {
      const upstream = continuesFrom(out, s, links.get(s));
      if (!upstream) continue;
      from.set(s, upstream.vpu);
      upstream.entry.to = p;
      const w = width.get(s) || 1;
      if (free(upstream.entry.col, w)) {
        base.set(s, upstream.entry.col);
        claim(upstream.entry.col, w);
      }
    }
    // Everything else first fit, in allocation order. With nothing continuing
    // this is exactly the old side-by-side placement.
    let columnsUsed = 0;
    for (const s of order) {
      const w = width.get(s) || 1;
      columnsUsed += w;
      if (base.has(s)) continue;
      let col = 0;
      while (col + w <= LINKS_PER_VPU && !free(col, w)) col++;
      // Nothing fits: run on past the edge, and let `overflow` say so.
      if (col + w > LINKS_PER_VPU) col = Math.max(LINKS_PER_VPU, ...[...taken].map((c) => c + 1));
      base.set(s, col);
      claim(col, w);
    }

    const blocks = [];
    let layerRows = 0;
    let backgroundRows = 0;

    for (const run of runs) {
      const at = base.get(run.screen);
      const cols = [...new Set(run.cells.flatMap((c) => c.outputs))]
        .sort((a, b) => a - b)
        .map((o) => at + o - 1);
      const height = capacityToLinks(run.capability) || 1;

      // The bar breaks where a link would have to cross the centre line. A
      // capacity-2 layer on an optimized VPU is exempt — that is what Optimized
      // mode buys (§5.5.6) — so it keeps one unbroken bar.
      const unbroken = optimizedVpu.has(p) && height >= 2;
      const pieces = [];
      for (const c of cols) {
        const tail = pieces[pieces.length - 1];
        const sameSide =
          tail &&
          Math.floor(tail[tail.length - 1] / SCALING_ENGINE_BOUNDARY) ===
            Math.floor(c / SCALING_ENGINE_BOUNDARY);
        if (tail && (unbroken || sameSide)) tail.push(c);
        else pieces.push([c]);
      }
      if (!pieces.length) pieces.push([at]);

      const start = run.background ? LINKS_PER_VPU + backgroundRows : layerRows;
      const total = pieces.length * height;
      if (run.background) backgroundRows += total;
      else layerRows += total;

      pieces.forEach((piece, i) => {
        // Mixers whose outputs land in this piece — the ones that carry it.
        const cells = run.cells.filter((c) =>
          c.outputs.some((o) => piece.includes(at + o - 1)),
        );
        blocks.push({
          screen: run.screen,
          layer: run.layer,
          background: run.background,
          section: run.background ? 'background' : 'layer',
          capability: run.capability,
          cutnfill: cells[0]?.rec.cutnfillCapa,
          mixers: cells.map((c) => c.id),
          slices: [...new Set(cells.map((c) => c.slice))].sort((a, b) => a - b),
          // The output links this piece drives, as the screen numbers them.
          outputs: piece.map((c) => c - at + 1),
          row: start + i * height,
          height,
          cols: piece,
          // A renderer reading only one mixer per block still gets a real one.
          mixer: cells[0]?.id,
          slice: cells[0]?.slice,
          size: 1,
          crossesBoundary: piece.some((c) => c >= SCALING_ENGINE_BOUNDARY),
          spansBoundary:
            piece.some((c) => c < SCALING_ENGINE_BOUNDARY) &&
            piece.some((c) => c >= SCALING_ENGINE_BOUNDARY),
          // Occupies a layer link beyond the run's first — the manual's hook.
          wrapped: i > 0,
        });
      });
    }

    out.push({
      vpu: p,
      fitted,
      blocks,
      rowsUsed: layerRows,
      backgroundRows,
      // Where each screen sits on the output links, for the header band, and
      // which VPU it continues from when its links run in from an earlier one.
      // `to` is filled in by the later VPU that continues it.
      screens: order.map((s) => {
        const entry = {
          screen: s,
          col: base.get(s),
          width: width.get(s) || 1,
          outputs: [...links.get(s)].sort((a, b) => a - b),
        };
        if (from.has(s)) entry.from = from.get(s);
        return entry;
      }),
      columnsUsed,
      overflow: layerRows > LINKS_PER_VPU || columnsUsed > LINKS_PER_VPU,
      spare: ids.filter((id) => mixers?.[id]?.isAvailable && !mixers[id].isEnabled).length,
      placement: 'reported-columns',
    });
  }
  return out;
}

/**
 * The nearest earlier VPU a screen continues from: the last grid so far holding
 * the same screen on any of the same output links. A screen on an earlier VPU
 * but on DIFFERENT links is §5.5.5's wider screen, not a continuation, and
 * answers null.
 */
function continuesFrom(grids, screen, links) {
  for (let i = grids.length - 1; i >= 0; i--) {
    const entry = (grids[i].screens || []).find((s) => s.screen === screen);
    if (!entry) continue;
    if (entry.outputs.some((o) => links.has(o))) return { vpu: grids[i].vpu, entry };
  }
  return null;
}

/**
 * How the VPU cards are laid out: one stack per chain of continuing VPUs, each
 * stack in the order the signal runs, so an output link leaving the bottom of
 * one card enters the top of the next. `from` always names an earlier VPU —
 * `buildLinkGrid` only looks back — so within a stack that order is simply
 * ascending. VPUs that continue nothing stand alone.
 *
 * @param {ReturnType<typeof buildLinkGrid>} grids
 * @returns {number[][]} VPU numbers, one array per stack, stacks in VPU order
 */
export function stackVpus(grids) {
  const parent = new Map((grids || []).map((g) => [g.vpu, g.vpu]));
  const root = (v) => {
    while (parent.get(v) !== v) v = parent.get(v);
    return v;
  };
  for (const g of grids || []) {
    for (const s of g.screens || []) {
      if (s.from !== undefined && parent.has(s.from)) parent.set(root(g.vpu), root(s.from));
    }
  }
  const stacks = new Map();
  for (const g of grids || []) {
    const r = root(g.vpu);
    if (!stacks.has(r)) stacks.set(r, []);
    stacks.get(r).push(g.vpu);
  }
  return [...stacks.values()]
    .map((members) => members.sort((a, b) => a - b))
    .sort((a, b) => a[0] - b[0]);
}

/**
 * Lay the enabled mixers of every processor onto its 8x8 link field.
 *
 * Fallback for data with no output-pipe allocation — see buildLinkGrid, which
 * uses the device's own columns when they are there.
 *
 * @returns {{vpu:number, fitted:boolean, blocks:Array, rowsUsed:number}[]}
 *   blocks are `{screen, layer, slice, capability, col, row, size, wrapped}`
 *   in LINK units, so a renderer can draw straight onto an 8x8 field.
 */
export function deriveLinkGrid(mixers) {
  const out = [];

  for (let p = 1; p <= PROCESSORS; p++) {
    const ids = MIXER_IDS.filter((id) => parseMixerId(id).processor === p);
    const fitted = ids.some((id) => mixers?.[id]?.isAvailable);
    const enabled = ids.filter((id) => mixers?.[id]?.isEnabled);

    // Preserve the device's own ordering of (screen, layer) runs.
    const runs = [];
    const index = new Map();
    for (const id of enabled) {
      const m = mixers[id];
      const key = `${m.usedInScreen} ${m.usedInLayer}`;
      if (!index.has(key)) {
        index.set(key, runs.length);
        runs.push({ screen: m.usedInScreen, layer: m.usedInLayer, capability: m.capability, cells: [] });
      }
      runs[index.get(key)].cells.push({ id, slice: m.slice });
    }
    for (const r of runs) r.cells.sort((a, b) => a.slice - b.slice);

    const blocks = [];
    let row = 0;
    for (const run of runs) {
      const size = capacityToLinks(run.capability) || 1;
      // The field is 8 links wide, so this many blocks sit on one layer link.
      const perBand = Math.max(1, Math.floor(LINKS_PER_VPU / size));
      run.cells.forEach((cell, i) => {
        const band = Math.floor(i / perBand);
        const col = (i % perBand) * size;
        blocks.push({
          mixer: cell.id,
          screen: run.screen,
          layer: run.layer,
          capability: run.capability,
          slice: cell.slice,
          col,
          row: row + band * size,
          size,
          // Occupies an additional layer link beyond the run's first (§5.5.4).
          wrapped: band > 0,
          // Sits past the scaling-engine boundary of 4 output links.
          crossesBoundary: col >= SCALING_ENGINE_BOUNDARY,
        });
      });
      const bands = Math.max(1, Math.ceil(run.cells.length / perBand));
      row += bands * size;
    }

    out.push({
      vpu: p,
      fitted,
      blocks,
      rowsUsed: row,
      overflow: row > LINKS_PER_VPU,
      spare: ids.filter((id) => mixers?.[id]?.isAvailable && !mixers[id].isEnabled).length,
    });
  }

  return out;
}

/**
 * Which output each of a screen's output links is — and so which region and
 * plug — for the header over the grid's columns.
 *
 * The grid's columns are the screen's own link numbers (`reportedOutputs`), and
 * nothing in the mixer table names the output behind them. The outputs do: each
 * says which screen it is in (`usedInScreenAux`), which region of it
 * (`usedInRegion`), and its capacity, and a capacity-2 output is two links wide.
 * So the screen's links are dealt out over its outputs in output-number order,
 * each output taking as many links as its capacity — the same accounting the
 * device's `usedOutputCapabilities` does.
 *
 * THE ORDER IS AN ASSUMPTION. That a screen numbers its links in the order of
 * its outputs' numbers is the only order the object model offers, and it has not
 * been checked on hardware: the Aquilon C went before the outputs were read. It
 * is checked against the screen's own figures instead — when the outputs found
 * do not add up to the screen's `outputCount` and `usedOutputCapabilities`, the
 * screen is marked inconsistent and a renderer should draw nothing for it
 * rather than a header that looks right.
 *
 * @param {object} outputs by output number: `{screen, region, capability, label?, type?, card?, physical?}`
 *   — `screen` is the screen it is assigned to (`NONE` when unassigned)
 * @param {object} [screenStatus] per-screen resource status, to check against
 * @returns {Map<string, {runs: Array<{output, region, capability, first, last}>, links, consistent}>}
 *   per screen: one run per output, `first`..`last` the screen's links it carries
 */
export function screenOutputLinks(outputs, screenStatus) {
  const byScreen = new Map();
  const keys = Object.keys(outputs || {}).sort((a, b) => Number(a) - Number(b));
  for (const key of keys) {
    const o = outputs[key];
    if (!o || !/^S\d+$/.test(String(o.screen))) continue; // unassigned, or an aux
    if (!byScreen.has(o.screen)) byScreen.set(o.screen, { runs: [], links: 0, consistent: true });
    const s = byScreen.get(o.screen);
    const span = capacityToLinks(o.capability) || 1;
    s.runs.push({
      output: key,
      region: o.region === undefined || o.region === null ? null : String(o.region),
      capability: o.capability ?? null,
      label: o.label || '',
      type: o.type ?? null,
      card: o.card ?? null,
      physical: o.physical ?? null,
      first: s.links + 1,
      last: s.links + span,
    });
    s.links += span;
  }
  for (const [screen, s] of byScreen) {
    const st = (screenStatus || {})[screen];
    if (!st) continue;
    if (st.outputCount !== undefined && Number(st.outputCount) !== s.runs.length) s.consistent = false;
    if (
      st.usedOutputCapabilities !== undefined &&
      Number(st.usedOutputCapabilities) !== s.links
    ) {
      s.consistent = false;
    }
  }
  return byScreen;
}

/**
 * Which VPUs host a screen in Optimized mode.
 *
 * §5.5.6: Optimized mode is enabled for the WHOLE VPU when one screen on it uses
 * at least 5 output links and at least one layer of capacity 2, and it removes
 * the 4-output scaling-engine boundary. So the boundary belongs to the VPU, not
 * to the screen that triggered it, and a grid that draws it on an optimized VPU
 * is showing a constraint the device is not applying.
 *
 * `isOptimized` is reported per screen, so map screen -> its mixers -> their
 * processors. On the captured Aquilon C, S1 spends 6 output capabilities and
 * duly reports true, which makes VPU 1 optimized.
 */
export function optimizedVpus(mixers, screenStatus) {
  const optimised = new Set(
    Object.entries(screenStatus || {})
      .filter(([, st]) => st && st.isOptimized)
      .map(([id]) => id),
  );
  const vpus = new Set();
  if (!optimised.size) return vpus;
  for (const [id, rec] of Object.entries(mixers || {})) {
    if (!rec || !rec.isEnabled) continue;
    if (!optimised.has(String(rec.usedInScreen))) continue;
    const parsed = parseMixerId(id);
    if (parsed) vpus.add(parsed.processor);
  }
  return vpus;
}

/**
 * Which mixers differ between the running mapping and the staged one.
 *
 * The output links matter as much as the properties — a staged configuration
 * can move a layer onto different links while every other value stays put, and
 * comparing only `@props` reports that as no change at all. On the captured
 * Aquilon C the running map interleaves S1 across links 1 and 3 while the
 * staged one packs it onto 1 and 2, and nothing else differs.
 */
export function diff(current, next) {
  const out = [];
  for (const id of MIXER_IDS) {
    const a = (current || {})[id];
    const b = (next || {})[id];
    if (!a && !b) continue;
    const changed = [];

    for (const p of ['isAvailable', ...MIXER_PROPS]) {
      const av = a ? a[p] : undefined;
      const bv = b ? b[p] : undefined;
      if (av !== bv) changed.push({ prop: p, from: av, to: bv });
    }

    const pipeOf = (rec, k) => {
      const v = rec && rec.mixerAllocation ? rec.mixerAllocation[`usedOnOutPipe${k}`] : undefined;
      return v === 'NONE' ? undefined : v;
    };
    for (let k = 1; k <= OUT_PIPES; k++) {
      const av = pipeOf(a, k);
      const bv = pipeOf(b, k);
      if (av !== bv) {
        changed.push({ prop: `link ${k}`, from: av ?? '—', to: bv ?? '—' });
      }
    }

    if (changed.length) out.push({ mixer: id, changed });
  }
  return out;
}
